CREATE TABLE memory_derivations(id uuid NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces,run_id uuid NOT NULL,input_hash text NOT NULL,extractor_version text NOT NULL DEFAULT 'source-v1',schema_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,input_hash,extractor_version),FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE TABLE memory_contexts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,conversation_id uuid NOT NULL,scope_key text NOT NULL,UNIQUE(workspace_id,id),UNIQUE(workspace_id,conversation_id,scope_key),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE TABLE memory_entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,context_id uuid NOT NULL,canonical_name text NOT NULL,source_message_id uuid NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,context_id) REFERENCES memory_contexts(workspace_id,id),FOREIGN KEY(workspace_id,source_message_id) REFERENCES messages(workspace_id,id));
CREATE TABLE memory_episodes(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,source_role text NOT NULL,observed_at timestamptz NOT NULL,content_hash text NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,id) REFERENCES messages(workspace_id,id));
CREATE TABLE memory_assertions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,context_id uuid NOT NULL,entity_id uuid NOT NULL,predicate text NOT NULL,typed_value jsonb NOT NULL,epistemic_status text NOT NULL CHECK(epistemic_status IN ('reported','inferred','disputed')),source_message_id uuid NOT NULL,source_span text NOT NULL,lineage_root_id uuid NOT NULL,derivation_id uuid NOT NULL,valid_from timestamptz,valid_to timestamptz,time_precision text NOT NULL CHECK(time_precision IN ('unknown','day','instant')),known_from timestamptz NOT NULL DEFAULT now(),known_to timestamptz,supersedes_id uuid,UNIQUE(workspace_id,id),FOREIGN KEY(id) REFERENCES memories(id),FOREIGN KEY(workspace_id,context_id) REFERENCES memory_contexts(workspace_id,id),FOREIGN KEY(workspace_id,entity_id) REFERENCES memory_entities(workspace_id,id),FOREIGN KEY(workspace_id,source_message_id) REFERENCES memory_episodes(workspace_id,id),FOREIGN KEY(workspace_id,lineage_root_id) REFERENCES memory_episodes(workspace_id,id),FOREIGN KEY(workspace_id,derivation_id) REFERENCES memory_derivations(workspace_id,id),FOREIGN KEY(workspace_id,supersedes_id) REFERENCES memory_assertions(workspace_id,id),CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>valid_from));
CREATE TABLE memory_decisions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,assertion_id uuid NOT NULL,status text NOT NULL DEFAULT 'reported' CHECK(status='reported'),FOREIGN KEY(workspace_id,assertion_id) REFERENCES memory_assertions(workspace_id,id));
CREATE TABLE memory_commitments(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,assertion_id uuid NOT NULL,due_at timestamptz,due_timezone text,state text NOT NULL DEFAULT 'intended' CHECK(state='intended'),FOREIGN KEY(workspace_id,assertion_id) REFERENCES memory_assertions(workspace_id,id));
CREATE INDEX memory_assertions_source ON memory_assertions(workspace_id,source_message_id);
CREATE INDEX memory_assertions_temporal ON memory_assertions(workspace_id,context_id,valid_from,valid_to,known_from,known_to);
